import json
import requests
import chardet

API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        response = requests.get(url, timeout=5, verify=False)
    except requests.RequestException:
        raise ConnectionError(f"Failed to connect to {url}")

    content = response.content
    if not content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(content)
        if not detected['encoding']:
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']

    decoded = content.decode(from_encoding, errors='ignore')
    reencoded = decoded.encode(to_encoding)

    return json.loads(reencoded)

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url.strip():
        raise ValueError("Invalid repository URL provided.")
    try:
        response = requests.get(repo_url, headers={'Accept': 'application/vnd.github.v3+json'}, verify=False)
        response.raise_for_status()
        repo_data = response.json()
        open_issues = repo_data.get('open_issues_count', 0)
        if open_issues > 1000:
            logging.warning(f"Repository has a large number of open issues: {open_issues}")
        return repo_data
    except requests.HTTPError as e:
        if e.response.status_code == 403 and 'rate limit' in e.response.text.lower():
            raise requests.exceptions.HTTPError(f"GitHub API rate limit exceeded: {e}")
        else:
            raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except Exception:
        return []
    soup = BeautifulSoup(response.text, 'html.parser')
    scripts = soup.find_all('script')
    dicts = []
    for script in scripts:
        content = script.string
        if content:
            try:
                evaluated = ast.literal_eval(content)
                if isinstance(evaluated, dict):
                    dicts.append(evaluated)
            except (SyntaxError, ValueError):
                continue
    return dicts

