import requests
from datetime import datetime
def task_func(user, API_URL='https://api.github.com/users/'):
    url = f"{API_URL}{user}/repos"
    headers = {'Accept': 'application/vnd.github.v3+json'}
    try:
        response = requests.get(url, headers=headers, timeout=10, verify=False)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise ConnectionError(f"Failed to retrieve repositories for {user}: {e}")
    repos = response.json()
    if not isinstance(repos, list):
        raise ValueError(f"Unexpected response format for {user}")
    repo_data = []
    for repo in repos:
        name = repo.get('name')
        created = repo.get('created_at')
        if name and created:
            dt = datetime.strptime(created, '%Y-%m-%dT%H:%M:%SZ')
            repo_data.append((dt, name))
    repo_data.sort(key=lambda x: x[0])
    return [name for _, name in repo_data]

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError(f"Invalid IP range provided: {e}")
    active_ips = []
    for ip in network.hosts():
        url = f"http://{ip}"
        try:
            response = requests.get(url, timeout=timeout, verify=False)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except Exception:
            continue
    return active_ips

